INSERT INTO "products" ("id","name","enabled","line_code","price","description","image_url","updated_at","specs","unit","pickup_price","delivery_price") VALUES('P025','天然茶皂',0,'P025',140,replace('自取140外送150\n\n📣即將調漲📣即將調漲📣即將調漲📣\n天然茶皂！來囉！要買要快唷！\n\n可以洗澡！洗頭！洗衣服都可以\n因為天然！可以放心使用\n\n回購第3次了 好用 我從頭洗到身體 \n外加洗衣服和餐具都很OK\n洗起來不錯喔!~~真的很好用 \n我都有送給我家親戚用他們都說很好用\n家中三歲小孩把彩色筆拿來亂畫...\n好怕很難洗...拿起了自家常用的茶籽肥皂來洗...\n想不到幾下子就OK.......\n\n#超平價超好用! #台灣製『皂』! \n#真港台灣60年老皂廠經驗傳承就是好洗好沖好乾淨👍\n\n老師傅精選原料親監親製： 天然油脂,椰子油,棕梠油,\n天然茶籽粉.....60年傳承調製完美配方,衣領、袖口、\n貼身衣物、污漬、血漬、兒童蠟筆、彩色筆都有神奇清潔力! \n\n茶籽配方去油去汚更升級,泡泡綿密好搓揉\n一沖即淨.....,皂性溫和不傷手.....\n軟硬適中,好握好拿不易軟爛\n使用前適度晾曬更可常保適當硬度... \n天然配方夏日沐浴好清爽!\n大量請密封保存，少量可放置陰涼通風\n\n☘️商品規格：一組10入\n☘️商品產地：台灣\n☘️商品尺寸：8.2公分*5.5公分*2.7公分（130公克','\n',char(10)),'https://ah-hsien-easy-buy-line.vannyai.workers.dev/images/products/P025?v=1784792010196','2026-07-23 10:16:48','一組10入','組',140,140);
INSERT INTO "products" ("id","name","enabled","line_code","price","description","image_url","updated_at","specs","unit","pickup_price","delivery_price") VALUES('P026','金園排骨厚切排骨',0,'P026',490,replace('《金園排骨厚切排骨》\n\n一組5片，自取490外送500\n\n🪂金字招牌60年\n🪂厚切手打的人氣美食\n\n🐽加菜的好選擇，讓你煮出一桌子好味  !\n🐽高級上選里肌肉，比市面上一般豬排多了25%的份量，價格卻這麼親民！\n🐽首先將肉片親手捶打，使其柔軟具彈性，再以獨門秘方醃漬入味；\n\n不論煎、烤、炸，充滿懷舊感的香味、\n『Q短短』的嚼勁，令人魂不守舍，實在太犯規了！\n簡單烹煮，即可美味上桌！送禮自用都合適，快速打理出一桌豐盛美味！\n通過SGS檢驗合格，保證不含動物用藥殘留，健康安全，敬請安心食用。\n\n🟡產地：台灣\n🟡重量規格：200g/包\n🟡保存方式：冷凍-18度c 一年','\n',char(10)),'https://ah-hsien-easy-buy-line.vannyai.workers.dev/images/products/P026?v=1784801785511','2026-07-24 06:47:55','200g/包','1組5片',490,490);
INSERT INTO "products" ("id","name","enabled","line_code","price","description","image_url","updated_at","specs","unit","pickup_price","delivery_price") VALUES('P027','挪威薄鹽鯖魚片',0,'P027',250,replace('🐟【薄鹽北大西洋挪威鯖魚片(特大)】\n\n🐟北大西洋直送｜厚肥飽滿｜熱銷NO.1\n\n✔️選用大尾鯖魚，肉厚肥美、油脂均勻\n✔️Omega-3、DHA、EPA滿滿，健身族、成長期少年、銀髮族都適合\n✔️拆封即料理：香煎、氣炸、烤箱通通OK\n✔️10分鐘上桌，下飯王！配飯、配沙拉、便當主菜，都是穩穩的主角。\n\n🍴料理小撇步：\n乾煎出金黃焦脆，擠檸檬更清爽；氣炸快速零油煙；烤箱一次搞定全家份量。\n\n🔥數量有限，缺貨就要等！\n👉手刀下單，囤起來才安心！\n\n⚠️遇缺貨每家工廠用的袋子顏色會不一樣、會隨機出貨能接者再下單！\n\n📍規格：180-220g±20g/片\n📍產地：挪威\n📍保存期限：冷凍18個月\n📍保存方式：冷凍存放於-18度C以下','\n',char(10)),'https://ah-hsien-easy-buy-line.vannyai.workers.dev/images/products/P027?v=1784875366445','2026-07-24 08:06:14','一組3片','組',NULL,NULL);
INSERT INTO "products" ("id","name","enabled","line_code","price","description","image_url","updated_at","specs","unit","pickup_price","delivery_price") VALUES('P028','香酥蛋餅皮',1,'P028',40,replace('🤩月銷售量達數萬包....真的不誇張！🤩\n\n👪迎接開學季！📚 CP值最高的早餐聖品，美味開團 ~\n🌮不吃外面的酸甜油膩，家庭健康自己把關🌮\n\n💘打敗市面上所有蛋餅皮、真材實料\n💘軟嫩不乾柴，煎起來邊邊會酥酥的👍\n💘香味十足‼️✨✨\n💘冷凍保存，隨時想吃都有😂\n💘甜的鹹的口味蛋餅，任由搭配‼️\n💘早餐宵夜必備食材\n\n🔰重量：550g+-10%\n🔰規格：10片裝一包，30包/箱\n🔰商品分類：●📏開學季必備系列📏','\n',char(10)),'https://ah-hsien-easy-buy-line.vannyai.workers.dev/images/products/P028?v=1784880407805','2026-07-24 08:40:32','1包40   3包110','包',40,110);
